parameters.text:
=Analyze the following lead data and generate a professional Quote and Statement of Work. You must ensure absolute compliance with AS 3740 (Waterproofing of domestic wet areas) and AS 3958.1 (Ceramic tiles). Output strictly in the defined JSON format without markdown wrappers.

Lead Data:
{{ $json.body }}

parameters.jsCode:
const inputData = $input.first().json.body; // Data received back from Editor.js portal
const client = inputData.client;
const items = inputData.lineItems;

let subtotal = 0;
const processedItems = items.map(item => {
    const rowTotal = item.qty * item.unitPrice;
    subtotal += rowTotal;
    return {
      ...item,
        rowTotal: rowTotal.toFixed(2),
        unitPrice: item.unitPrice.toFixed(2)
    };
});

const discountRate = 0.20;
const discountAmount = subtotal * discountRate;
const taxableAmount = subtotal - discountAmount;
const gst = taxableAmount * 0.10;
const grandTotal = taxableAmount + gst;

let tableRows = "";
processedItems.forEach(item => {
    tableRows += `<tr><td style="padding:12px; border-bottom:1px solid #eee;">${item.description}</td><td style="padding:12px; border-bottom:1px solid #eee;">${item.qty}</td><td style="padding:12px; border-bottom:1px solid #eee;">$${item.unitPrice}</td><td style="padding:12px; border-bottom:1px solid #eee;">10.0%</td><td style="padding:12px; border-bottom:1px solid #eee;">$${item.rowTotal}</td></tr>`;
});

const indexHtml = `<!DOCTYPE html><html lang="en"><head><style>body { font-family: 'Helvetica Neue', Arial, sans-serif; color: #2c3e50; margin: 40px; } table { width: 100%; border-collapse: collapse; margin-top: 40px; font-size: 14px; } th { background-color: #34495e; color: #ffffff; text-align: left; padding: 12px; }.summary-box { background-color: #ecf0f1; padding: 20px; border-left: 5px solid #3498db; margin-top: 30px; }.totals { float: right; width: 350px; margin-top: 30px; border-top: 2px solid #bdc3c7; padding-top: 15px; }.total-line { display: flex; justify-content: space-between; margin-bottom: 8px; font-size: 14px; }.grand-total { font-size: 18px; font-weight: bold; color: #2980b9; margin-top: 15px; padding-top: 15px; border-top: 1px solid #ecf0f1; }</style></head><body><div style="display:flex; justify-content:space-between;"><div><h3 style="color:#7f8c8d; margin-bottom:5px; font-size:12px; text-transform:uppercase;">Recipient</h3><p style="margin:0; font-size:16px;"><strong>${client.name}</strong><br>${client.address}</p></div><div><h3 style="color:#7f8c8d; margin-bottom:5px; font-size:12px; text-transform:uppercase;">Quote Date</h3><p style="margin:0; font-size:16px;"><strong>${new Date().toLocaleDateString()}</strong></p></div></div><div class="summary-box"><p style="margin:0; line-height:1.6;">${inputData.projectSummary}</p></div><table><thead><tr><th>DESCRIPTION</th><th>QTY</th><th>UNIT PRICE</th><th>GST</th><th>TOTAL</th></tr></thead><tbody>${tableRows}</tbody></table><div class="totals"><div class="total-line"><span>Subtotal:</span><span>$${subtotal.toFixed(2)}</span></div><div class="total-line"><span>Discount (20%):</span><span>-$${discountAmount.toFixed(2)}</span></div><div class="total-line"><span>GST:</span><span>$${gst.toFixed(2)}</span></div><div class="total-line grand-total"><span>Total:</span><span>$${grandTotal.toFixed(2)}</span></div></div></body></html>`;

const headerHtml = `<!DOCTYPE html><html lang="en"><body><div style="width: 100%; display: flex; justify-content: space-between; padding: 15px 40px; border-bottom: 3px solid #34495e; font-family: 'Helvetica Neue', sans-serif;"><h1 style="margin: 0; color: #2980b9; font-size: 22px; font-weight: 700; letter-spacing: 1px;">REVIVE PROPERTY CO.</h1><div style="text-align: right;"><h2 style="margin: 0; font-size: 16px; color: #7f8c8d;">QUOTE</h2><p style="margin: 2px 0 0 0; font-size: 11px; color: #95a5a6;">Ref: RV_QT_${Math.floor(Math.random() * 10000)}</p></div></div></body></html>`;

const footerHtml = `<!DOCTYPE html><html lang="en"><body><div style="width: 100%; text-align: center; font-family: 'Helvetica Neue', sans-serif; font-size: 11px; color: #95a5a6; padding-top: 15px; border-top: 1px solid #ecf0f1;">Page <span class="pageNumber"></span> of <span class="totalPages"></span> | PENDING_DIGITAL_VERIFICATION | Gair Family Pty Ltd ABN: 19634697340</div></body></html>`;

return [{json: { indexHtml, headerHtml, footerHtml }}];
